import {onMounted,ref} from 'vue'
import {courseService} from '../../api/category/category'
import {recursionTree} from '../../utils/utils'
import {useUserStore} from '../../stores/user'
import {openAssistant} from '../../stores/assistant'
import BottomNav from '../../components/BottomNav/BottomNav.vue'
const store=useUserStore(),query=ref(''),categories=ref<any[]>([]),subcategories=ref<any[]>([]),sections=ref<any[]>([]),categoryIndex=ref(0),loading=ref(true),error=ref(''),failedCovers=ref<Record<number,boolean>>({})
let loadVersion=0
function go(url:string){uni.navigateTo({url})}
function search(){go('/pages/search/search?q='+encodeURIComponent(query.value.trim()))}
function browse(item:any){go('/pages/search/search?category3Id='+item.id+'&pageTitle='+encodeURIComponent(item.name))}
async function selectCategory(index:number){categoryIndex.value=index;const item=categories.value[index];if(!item){loading.value=false;return}const version=++loadVersion;loading.value=true;error.value='';subcategories.value=[];try{const [books,nav]=await Promise.all([courseService.getCategory1IdData(item.id),courseService.getCategory1IdTopList(item.id)]);if(version!==loadVersion)return;sections.value=(books.data||[]).filter((s:any)=>s.list?.length);subcategories.value=nav.data||[]}catch(e){if(version===loadVersion){sections.value=[];error.value='内容加载失败，请稍后重试。'}}finally{if(version===loadVersion)loading.value=false}}
async function loadCategories(){loading.value=true;error.value='';try{const result=await courseService.getAllCategory();recursionTree(result.data,'name','categoryName','categoryChild');recursionTree(result.data,'id','categoryId','categoryChild');categories.value=result.data as any[];await selectCategory(categoryIndex.value)}catch(e){error.value='暂时无法加载分类，请检查服务连接。';loading.value=false}}
onMounted(loadCategories)
